 <script>
 const COLORS=[{name:'Coral',hex:'#ed6b62',dark:'#c64e4a',light:'#ffe5df',icon:'♥',start:0},{name:'Sky',hex:'#5489e8',dark:'#366bc2',light:'#e1edff',icon:'✦',start:10},{name:'Honey',hex:'#edb94e',dark:'#c78d27',light:'#fff0c8',icon:'✿',start:20},{name:'Lilac',hex:'#9270d7',dark:'#7354b8',light:'#ede4ff',icon:'❀',start:30}];
-const TRACK=[];for(let x=7;x<=12;x++)TRACK.push([x,2]);for(let y=3;y<=12;y++)TRACK.push([12,y]);for(let x=11;x>=2;x--)TRACK.push([x,12]);for(let y=11;y>=3;y--)TRACK.push([2,y]);for(let x=3;x<=6;x++)TRACK.push([x,2]);
+const TRACK=[];for(let x=7;x<=12;x++)TRACK.push([x,2]);for(let y=3;y<=12;y++)TRACK.push([12,y]);for(let x=11;x>=2;x--)TRACK.push([x,12]);for(let y=11;y>=3;y--)TRACK.push([2,y]);for(let x=3;x<=6;x++)TRACK.push([x,2]);TRACK.push([2,2]);
 // Correct the rectangular loop to 40 distinct squares, ordered clockwise from north.
 const HOME_LANES=[[[7,3],[7,4],[7,5],[7,6],[7,7]],[[11,7],[10,7],[9,7],[8,7],[7,7]],[[7,11],[7,10],[7,9],[7,8],[7,7]],[[3,7],[4,7],[5,7],[6,7],[7,7]]];
 const SAFE=[0,10,20,30];const SVGNS='http://www.w3.org/2000/svg';const $=s=>document.querySelector(s);
 let state, sound=true, aiTimer=null;

