function legalMoves(){const pl=state.players[state.turn];if(!state.dice)return[];return pl.pawns.map((pos,i)=>pos===-1?(state.dice===6?i:null):(pos<44&&pos+state.dice<=44?i:null)).filter(i=>i!==null)}
function render(){const pl=state.players[state.turn],col=COLORS[state.turn];$('#turnCard').style.setProperty('--active',col.hex);$('#turnIcon').textContent=col.icon;$('#turnName').textContent=col.name;$('#turnSub').textContent=state.winner!==null?'Game complete':pl.human?'Your turn · roll the dice':'Thinking…';$('#roundLabel').textContent='ROUND '+state.round;
 const btn=$('#rollBtn'),hint=$('#selectHint');btn.disabled=state.phase!=='roll'||state.winner!==null||!pl.human;btn.innerHTML=state.winner!==null?'<span>🏆</span> Game over':state.phase==='select'?'<span>☝</span> Choose a pawn':'<span>⚄</span> Roll the dice';
 if(state.phase==='select'){hint.textContent=pl.human?'Choose one of the glowing pawns':'Choosing a pawn…';$('#diceHeadline').textContent=`You rolled a ${state.dice}!`;$('#diceCaption').textContent=state.dice===6?'A six — roll again after your move!':'Move a pawn';}
 else if(state.winner!==null){hint.textContent=`${COLORS[state.winner].name} takes the meadow!`;$('#diceHeadline').textContent='Beautifully played!';$('#diceCaption').textContent='All five pawns made it home.'}
 else{hint.textContent=pl.human?'Tap the button to begin your turn':'The dice are tumbling…';$('#diceHeadline').textContent=pl.human?'Ready to roll?':'Good luck, '+col.name+'!';$('#diceCaption').textContent=pl.human?'A six gets a pawn moving!':'Your meadow friends are playing';}
 const pipmap={1:[4],2:[0,8],3:[0,4,8],4:[0,2,6,8],5:[0,2,4,6,8],6:[0,2,3,5,6,8]},pips=[...$('#dice').children];pips.forEach((pip,i)=>pip.classList.toggle('on',(pipmap[state.dice||1]||[]).includes(i)));$('#dice').setAttribute('aria-label','Dice showing '+(state.dice||1));
 $('#playerList').innerHTML=state.players.map((p,i)=>{const done=p.pawns.filter(v=>v===44).length,home=p.pawns.filter(v=>v===-1).length;return `<div class="player-row ${i===state.turn&&state.winner===null?'active':''}" style="--c:${COLORS[i].hex}"><span class="player-icon">${COLORS[i].icon}</span><span class="player-info"><b>${COLORS[i].name}${p.human?'':' <small>CPU</small>'}</b><small>${done} home · ${home} in patch</small></span><span class="pawn-count"><em>${p.pawns.length-home-done}</em>/5 out</span></div>`}).join('');
 state.legal=state.phase==='select'?legalMoves():[];buildBoard();}
function playTone(freq=520,duration=.08){if(!sound)return;try{const ctx=new(window.AudioContext||window.webkitAudioContext)(),o=ctx.createOscillator(),g=ctx.createGain();o.frequency.value=freq;o.type='sine';g.gain.setValueAtTime(.035,ctx.currentTime);g.gain.exponentialRampToValueAtTime(.001,ctx.currentTime+duration);o.connect(g);g.connect(ctx.destination);o.start();o.stop(ctx.currentTime+duration);o.onended=()=>ctx.close()}catch{}}
function rollDice(){if(state.phase!=='roll'||state.winner!==null)return;const dice=$('#dice');dice.classList.remove('rolling');void dice.offsetWidth;dice.classList.add('rolling');playTone(360,.12);state.dice=1+Math.floor(Math.random()*6);state.phase='select';state.legal=legalMoves();render();if(state.legal.length===0){$('#selectHint').textContent='No moves this time — passing along';$('#rollBtn').disabled=true;setTimeout(()=>endTurn(false),850);return}if(!state.players[state.turn].human)scheduleAI()}
function movePawn(n){if(state.phase!=='select'||!state.legal?.includes(n))return;const p=state.turn,pl=state.players[p],old=pl.pawns[n],roll=state.dice;pl.pawns[n]=old===-1?0:old+roll;const dest=pl.pawns[n];let captured=0;if(dest<40){const coord=trackCoord(p,dest),global=(COLORS[p].start+dest)%40;if(!SAFE.includes(global)){state.players.forEach((other,op)=>{if(op!==p)other.pawns=other.pawns.map(pos=>{if(pos>=0&&pos<40){const cc=trackCoord(op,pos);if(cc[0]===coord[0]&&cc[1]===coord[1]){captured++;return-1}}return pos})})}}
 playTone(captured?760:620,.12);state.dice=null;state.selected=null;if(pl.pawns.every(v=>v===44)){state.winner=p;state.phase='done';render();showModal('🏆',`${COLORS[p].name} wins!`,'Every pawn made it home. What a lovely run around the meadow.',[['Play again','primary',()=>startGame(humanCount())]]);return}
 const extra=roll===6;if(extra){state.phase='roll';$('#diceHeadline').textContent=captured?'A capture! Roll again!':'Nice six! Roll again!';$('#diceCaption').textContent=captured?`${captured} rival pawn${captured>1?'s':''} sent back to the patch.`:'You earned another turn.'}else advanceTurn();render();if(!state.players[state.turn].human)scheduleAI()}
function advanceTurn(){state.turn=(state.turn+1)%4;state.turns++;if(state.turn===0)state.round++;state.phase='roll';state.dice=null}
function endTurn(extra=false){if(!extra)advanceTurn();else state.phase='roll';state.dice=null;render();if(!state.players[state.turn].human)scheduleAI()}
function scheduleAI(){clearTimeout(aiTimer);if(state.winner!==null)return;aiTimer=setTimeout(()=>{if(state.phase==='roll'){rollDice()}else if(state.phase==='select'){const pl=state.players[state.turn],moves=state.legal||[];if(!moves.length){endTurn(false);return}let n=moves.find(i=>pl.pawns[i]===-1);if(n===undefined){n=moves.find(i=>pl.pawns[i]+state.dice===44);if(n===undefined)n=moves[Math.floor(Math.random()*moves.length)]}movePawn(n)}},750)}
function humanCount(){return state.players.filter(p=>p.human).length}
function startGame(humans=1){clearTimeout(aiTimer);state=freshState();state.players.forEach((p,i)=>p.human=i<humans);render();if(!state.players[0].human)scheduleAI()}
function showModal(emoji,title,text,actions){$('#modalEmoji').textContent=emoji;$('#modalTitle').textContent=title;$('#modalText').textContent=text;const box=$('#modalActions');box.innerHTML='';actions.forEach(([label,cls,fn])=>{const b=document.createElement('button');b.textContent=label;b.className=cls||'';b.onclick=()=>{hideModal();fn()};box.appendChild(b)});$('#modalOverlay').classList.remove('hidden')}
function hideModal(){$('#modalOverlay').classList.add('hidden')}
function openHelp(){showModal('🌼','How to play','Four players race clockwise around the meadow. Roll a six to bring a pawn out of your picnic patch. Move the number shown; land on an unprotected rival to send them back. The four colored start spots are safe. You need an exact roll to reach the star-shaped home lane finish. Roll a six for another turn. You play Coral; the other meadows are lively CPU players.',['Got it','primary',()=>{}])}
$('#rollBtn').addEventListener('click',rollDice);$('#helpBtn').addEventListener('click',openHelp);$('#restartBtn').addEventListener('click',()=>showModal('↻','New meadow?','Start a fresh four-player game. Choose how many players are human; remaining seats are filled by friendly CPU players.',[['1 human','',()=>startGame(1)],['2 humans','',()=>startGame(2)],['3 humans','',()=>startGame(3)],['4 humans','primary',()=>startGame(4)]]));$('#soundBtn').addEventListener('click',e=>{sound=!sound;e.currentTarget.textContent=sound?'♫':'♩';e.currentTarget.title=sound?'Sound on':'Sound off'});$('#modalOverlay').addEventListener('click',e=>{if(e.target.id==='modalOverlay')hideModal()});
state=freshState();render();
</script>

